
DROP TABLE "T_TERMINAL_AGENT_INFO";
CREATE TABLE "T_TERMINAL_AGENT_INFO" (
  "ID" NUMBER(11,0) NOT NULL,
  "AGENT_TYPE" VARCHAR2(64) NOT NULL,
  "FUNCTION_CODE" NUMBER NOT NULL,
  "ENTRUST_PROP" VARCHAR2(32),
  "QUOTE_TYPE" NUMBER,
  "MARKET" VARCHAR2(32),
  "ENTRUST_BS" VARCHAR2(32),
  "CREATE_TIME" DATE NOT NULL,
  "GP_CODE" VARCHAR2(64) NOT NULL,
  "TRIGGER_CODE" VARCHAR2(64) NOT NULL,
  "REMARK" VARCHAR2(255),
  "STATUS" NUMBER,
  PRIMARY KEY ("ID")
);

COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."ID" IS '主键';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."AGENT_TYPE" IS '终端类型';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."FUNCTION_CODE" IS '请求码';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."ENTRUST_PROP" IS '委托属性';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."QUOTE_TYPE" IS '行情类型';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."MARKET" IS '市场';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."ENTRUST_BS" IS '交易方向';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."GP_CODE" IS '接口分组';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."TRIGGER_CODE" IS '接口编号';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."REMARK" IS '备注';
COMMENT ON COLUMN "T_TERMINAL_AGENT_INFO"."STATUS" IS '状态';

